{
  "id": 71,
  "knowledge": "Projected Annual QoL Gain",
  "description": "Calculates the total expected Quality of Life points a patient will gain over a year based on their current cost-effectiveness and a given budget.",
  "definition": "\text{Projected Gain} = \text{Numeric value of treatment cost-effectiveness} \times \text{annual budget}"
}

{
  "id": 78,
  "knowledge": "Therapeutic Return on Investment (T-ROI)",
  "description": "Calculates the efficiency of therapy by measuring the rate of depression improvement per hour of therapy intensity.",
  "definition": "\text{T-ROI} = \frac{\text{Numeric value of depression improvement rate}}{\text{Numeric value of therapy intensity in hours per month}}"
}

{
  "id": 77,
  "knowledge": "Intensive Therapy Standard Compliance",
  "description": "A boolean check to determine if a patient's therapy intensity meets or exceeds a given threshold.",
  "definition": "\text{Compliance} = (\text{Numeric value of therapy intensity in hours per month} >= \text{threshold})"
}

{
  "id": 68,
  "knowledge": "Annual Treatment Benefit",
  "description": "The projected total reduction in depression score over a 12-month period.",
  "definition": "\text{Benefit} = \text{Numeric value of depression improvement rate} \times 12"
}

{
  "id": 89,
  "knowledge": "Insurance-Adjusted QoL Projection",
  "description": "A calculation that projects a patient's annual Quality of Life gain by applying an insurance-specific annual budget to their personal treatment cost-effectiveness rate.",
  "definition": "\text{Projection} = \text{cost-effectiveness rate} \times \text{budget}{\text{plan}}, \text{where } \text{budget}{\text{plan}} = \begin{cases} 6000 & \text{if insurance type = 'Private'} \\ 3500 & \text{if insurance type = 'Medicare'} \\ 2500 & \text{if insurance type = 'Medicaid'} \\ 0 & \text{otherwise} end{cases}"
}

{
  "id": 23,
  "knowledge": "Therapy Engagement",
  "description": "Illustrates the value of therapy engagement levels.",
  "definition": "Ranges from Low to High. Low indicates minimal participation, Medium indicates regular participation, and High indicates active engagement."
}

{
  "id": 73,
  "knowledge": "Break-Even Therapy Hours",
  "description": "Calculates the number of therapy hours a patient needs to receive to achieve a predefined 'clinically valuable' outcome threshold, based on their personal cost-effectiveness and billing rates.",
  "definition": "\text{Hours} = \frac{(\frac{\text{Quality of Life Threshold}}{\text{cost-effectiveness rate}}) / \text{exchange rate}}{\text{hourly rate}}"
}

{
  "id": 81,
  "knowledge": "Annual Goal Achievement",
  "description": "The projected number of recovery goals a patient is expected to achieve over a 12-month period, based on their current monthly velocity.",
  "definition": "\text{Annual Goals} = \text{Numeric value of recovery goal velocity} \times 12"
}

{
  "id": 88,
  "knowledge": "High QoL Gain Candidate",
  "description": "A classification for patients whose projected treatment benefits, measured in Quality of Life points, significantly exceed a defined clinical threshold based on their financial budget.",
  "definition": "A patient is flagged if their 'Projected Annual QoL Gain' is greater than 100."
}

